	/**
	 * Method to retrieve the LegalHold via LegalHoldFetchOneSummary
	 * @param 	summary LegalHoldFetchOneSummary
	 * @return 	LegalHoldFetchOneResponse
	 */
	public LegalHold getLegalHold( LegalHoldFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "LegalHoldFetchOneSummary arg cannot be null" );

		LegalHold entity = null;
		UUID id = summary.getLegalHoldId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a LegalHold using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


